/* Token Radar's dashboard theme: warm paper, ink navy, burnt-orange accent.
   The palette is five values; everything else is spacing, a hairline and a
   type step. No network: no URL is ever loaded from this file. */
:root {
  --paper: #f7f4ee;
  --surface: #fffdf8;
  --ink: #1d2733;
  --muted: #5d6b7a;
  --line: #ddd5c5;
  --accent: #b45309;
  --accent-soft: #fdf0dd;
  --teal: #0e7490;
  --red: #b91c1c;
  --radius: 10px;
  --radius-lg: 16px;
  --font-body: "Avenir Next", Avenir, "Segoe UI", system-ui, sans-serif;
  --font-num: "SF Mono", ui-monospace, Menlo, Consolas, monospace;
  --s1: 4px;
  --s2: 8px;
  --s3: 12px;
  --s4: 16px;
  --s5: 24px;
  --s6: 32px;
  --s7: 48px;
}

* { box-sizing: border-box; }
html { color-scheme: light; }
body {
  margin: 0;
  background: var(--paper);
  color: var(--ink);
  font: 400 15px/1.55 var(--font-body);
}
h1, h2, h3 { margin: 0; letter-spacing: -0.015em; }
h1 { font-size: 32px; line-height: 1.12; font-weight: 700; }
h2 { font-size: 19px; line-height: 1.25; font-weight: 700; }
h3 { font-size: 15px; line-height: 1.3; font-weight: 700; }
p { margin: 0; }
button, input, select { font: inherit; color: inherit; }
button { cursor: pointer; }
a { color: var(--accent); }
.skip { position: absolute; left: -9999px; top: 0; padding: var(--s2) var(--s4); background: var(--surface); border: 1px solid var(--line); z-index: 30; }
.skip:focus { left: var(--s4); top: var(--s4); }
:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }

.shell { max-width: 1280px; margin: 0 auto; padding: var(--s5) var(--s6) var(--s7); }
.masthead {
  display: flex; align-items: baseline; justify-content: space-between; gap: var(--s5);
  padding-bottom: var(--s4); border-bottom: 2px solid var(--ink);
}
.brand { display: flex; align-items: baseline; gap: var(--s3); }
.brand .dot { width: 11px; height: 11px; border-radius: 3px; background: var(--accent); display: inline-block; transform: rotate(45deg); }
.brand-name { font-family: var(--font-num); font-size: 13px; letter-spacing: 0.14em; text-transform: uppercase; }
.masthead-meta { display: flex; gap: var(--s4); color: var(--muted); font-size: 13px; }
.masthead-meta span { white-space: nowrap; }

.hero { padding: var(--s6) 0 var(--s5); }
.hero p { color: var(--muted); max-width: 70ch; margin-top: var(--s2); font-size: 16px; }
.stats { display: grid; grid-template-columns: repeat(4, 1fr); gap: var(--s3); margin-top: var(--s5); }
.stat { background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius-lg); padding: var(--s4) var(--s5); }
.stat b { display: block; font-family: var(--font-num); font-size: 26px; font-weight: 600; line-height: 1.2; }
.stat span { color: var(--muted); font-size: 13px; }

.toolbar {
  position: sticky; top: 0; z-index: 5;
  display: flex; flex-wrap: wrap; align-items: end; gap: var(--s3);
  padding: var(--s4) 0; background: var(--paper); border-top: 1px solid var(--line);
}
.field { display: grid; gap: var(--s1); }
.field label { color: var(--muted); font-size: 12px; }
.field input, .field select {
  min-height: 38px; padding: 0 var(--s3); border: 1px solid var(--line); border-radius: var(--radius);
  background: var(--surface); min-width: 170px;
}
.field input { min-width: 270px; }
.tabs { display: flex; gap: 2px; padding: 3px; border: 1px solid var(--line); border-radius: var(--radius); background: var(--surface); }
.tabs button { min-height: 32px; padding: 0 var(--s3); border: 0; border-radius: 7px; background: transparent; color: var(--muted); }
.tabs button[aria-pressed="true"] { background: var(--accent); color: #fff; }
.shown { margin-left: auto; color: var(--muted); font-size: 13px; align-self: center; }

.card { background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius-lg); overflow: hidden; }
.scroll { overflow-x: auto; }
table { width: 100%; border-collapse: collapse; font-size: 14px; }
caption { text-align: left; padding: var(--s4) var(--s5) var(--s2); color: var(--muted); font-size: 13px; }
th, td { padding: var(--s3) var(--s4); border-bottom: 1px solid var(--line); text-align: left; vertical-align: middle; }
thead th { color: var(--muted); font-size: 12px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.04em; white-space: nowrap; }
th button { display: inline-flex; align-items: center; gap: var(--s1); border: 0; background: none; padding: 0; color: inherit; font: inherit; text-transform: inherit; letter-spacing: inherit; }
th button:hover { color: var(--ink); }
tbody tr { cursor: pointer; }
tbody tr:hover { background: var(--accent-soft); }
tbody tr[data-selected="true"] { background: var(--accent-soft); box-shadow: inset 3px 0 0 var(--accent); }
.num { font-family: var(--font-num); font-variant-numeric: tabular-nums; white-space: nowrap; }
.rank-badge {
  display: inline-grid; place-items: center; min-width: 30px; height: 30px; padding: 0 6px;
  border-radius: 8px; background: var(--ink); color: #fff; font-family: var(--font-num); font-size: 13px;
}
.rank-badge.top { background: var(--accent); }
.pname { display: grid; gap: 1px; }
.pname b { font-weight: 650; }
.sub { color: var(--muted); font-size: 12px; }
.up { color: var(--teal); }
.down { color: var(--red); }
.value-cell { display: flex; align-items: center; gap: var(--s2); }
.meter { width: 110px; height: 7px; border-radius: 4px; background: #e9e2d2; overflow: hidden; flex: none; }
.meter i { display: block; height: 100%; background: var(--accent); }
.chip { display: inline-block; padding: 2px 8px; border-radius: 999px; background: #eef4f6; color: var(--teal); font-size: 12px; white-space: nowrap; }
.chip.live { background: #f6e8e8; color: var(--red); }

.model { margin-top: var(--s4); padding: var(--s5); display: grid; gap: var(--s3); }
.model .formula { font-family: var(--font-num); font-size: 13px; line-height: 1.8; color: var(--muted); overflow-wrap: anywhere; background: var(--paper); border: 1px solid var(--line); border-radius: var(--radius); padding: var(--s4); }
.factors { display: grid; grid-template-columns: repeat(4, 1fr); gap: var(--s3); }
.factor { border-top: 2px solid var(--accent); padding-top: var(--s3); }
.factor b { display: block; font-size: 14px; }
.factor span { color: var(--muted); font-size: 13px; }

.empty { padding: var(--s7) var(--s5); text-align: center; display: grid; gap: var(--s3); justify-items: center; }
.empty p { color: var(--muted); }
.btn { min-height: 38px; padding: 0 var(--s4); border: 1px solid var(--line); border-radius: var(--radius); background: var(--surface); }
.btn.primary { background: var(--accent); border-color: var(--accent); color: #fff; }
.note { margin-top: var(--s4); color: var(--muted); font-size: 13px; }

.drawer {
  position: fixed; top: 0; right: 0; bottom: 0; width: min(560px, 94vw); z-index: 20;
  background: var(--surface); border-left: 1px solid var(--line); padding: var(--s5);
  overflow-y: auto; box-shadow: -12px 0 32px rgba(29, 39, 51, 0.18);
}
.drawer[hidden] { display: none; }
.drawer-head { display: flex; align-items: start; justify-content: space-between; gap: var(--s4); }
.drawer-head > div { min-width: 0; }
.drawer-head .sub { overflow-wrap: anywhere; margin-top: var(--s1); }
.close { flex: none; min-width: 34px; min-height: 34px; padding: 0 var(--s2); border: 1px solid var(--line); border-radius: var(--radius); background: var(--surface); }
.drawer h2 { margin-top: var(--s1); }
.drawer-sec { margin-top: var(--s5); padding-top: var(--s4); border-top: 1px solid var(--line); }
.drawer-sec h3 { margin-bottom: var(--s2); }
.breakdown { display: grid; gap: var(--s2); font-family: var(--font-num); font-size: 13px; }
.breakdown div { display: flex; justify-content: space-between; gap: var(--s3); }
.breakdown span { color: var(--muted); }
.steps { margin: 0; padding-left: var(--s5); display: grid; gap: var(--s3); }
.steps li { padding-left: var(--s1); }
.steps b { display: block; font-weight: 550; }
.steps .cost { color: var(--muted); font-size: 12px; font-family: var(--font-num); }
.scrim { position: fixed; inset: 0; z-index: 15; background: rgba(29, 39, 51, 0.25); }
.scrim[hidden] { display: none; }

@media (max-width: 900px) {
  .shell { padding: var(--s4); }
  .stats { grid-template-columns: repeat(2, 1fr); }
  .factors { grid-template-columns: 1fr 1fr; }
  .field input { min-width: 0; width: 100%; }
  .masthead { flex-wrap: wrap; }
}
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { transition-duration: 0.01ms !important; animation-duration: 0.01ms !important; }
}
